    "css": "/* seerr-games: the discover page (a dark-first app). Colours only from var(--themarr-*). */\n\n.page {\n  width: 1100px;\n  height: 700px;\n  position: relative;\n  overflow: hidden;\n  display: flex;\n  background: var(--themarr-background);\n  color: var(--themarr-foreground);\n  font-family: \"IBM Plex Sans\", ui-sans-serif, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  font-size: 13px;\n  line-height: 1.4;\n}\n\n:where(.page) *,\n:where(.page) *::before,\n:where(.page) *::after {\n  box-sizing: border-box;\n}\n\n:where(.page) :is(h2, h3, h4, p, ul) {\n  margin: 0;\n  padding: 0;\n  font: inherit;\n}\n\n:where(.page) ul {\n  list-style: none;\n}\n\n:where(.page) :is(button, input) {\n  margin: 0;\n  padding: 0;\n  border: 0;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  text-align: inherit;\n}\n\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n.spacer {\n  flex: 1;\n}\n\n/* Icon rail */\n\n.rail {\n  width: 72px;\n  flex: 0 0 72px;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  gap: 14px;\n  padding: 16px 0;\n  background: var(--themarr-surface-1);\n  border-right: 1px solid var(--themarr-border);\n}\n\n.rail ul {\n  display: flex;\n  flex-direction: column;\n  gap: 14px;\n}\n\n.rail-brand {\n  width: 36px;\n  height: 36px;\n  border-radius: var(--themarr-radius);\n  background: var(--themarr-primary);\n}\n\n.rail-item {\n  width: 40px;\n  height: 40px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: var(--themarr-radius);\n  color: var(--themarr-muted-foreground);\n}\n\n.rail-item.is-active {\n  background: var(--themarr-accent);\n  color: var(--themarr-accent-foreground);\n}\n\n.rail-icon {\n  width: 16px;\n  height: 16px;\n  border: 2px solid currentColor;\n  border-radius: 4px;\n}\n\n/* Main area */\n\n.main {\n  flex: 1;\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  gap: 18px;\n  padding: 18px 24px;\n}\n\n.topbar {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.search {\n  flex: 1;\n  max-width: 420px;\n  padding: 9px 12px;\n  border: 1px solid var(--themarr-border);\n  border-radius: 999px;\n  background: var(--themarr-muted);\n  color: var(--themarr-foreground);\n}\n\n.search::placeholder {\n  color: var(--themarr-muted-foreground);\n  opacity: 1;\n}\n\n.waiting {\n  padding: 4px 10px;\n  border-radius: 999px;\n  background: var(--themarr-secondary);\n  color: var(--themarr-secondary-foreground);\n  font-size: 12px;\n}\n\n/* People: the optional tag token, else the accent. */\n.avatar {\n  width: 34px;\n  height: 34px;\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: 50%;\n  background: var(--themarr-tag, var(--themarr-accent));\n  color: var(--themarr-tag-foreground, var(--themarr-accent-foreground));\n  font-size: 12px;\n  font-weight: 600;\n}\n\n/* Featured game */\n\n.hero {\n  display: flex;\n  gap: 20px;\n  padding: 20px;\n  border: 1px solid var(--themarr-border);\n  border-radius: calc(var(--themarr-radius) + 6px);\n  background: var(--themarr-card);\n  color: var(--themarr-card-foreground);\n}\n\n.hero-poster {\n  width: 160px;\n  height: 210px;\n  flex: 0 0 160px;\n  border-radius: var(--themarr-radius);\n  background: var(--themarr-chart-1);\n}\n\n.hero-text {\n  min-width: 0;\n  display: flex;\n  flex-direction: column;\n  justify-content: center;\n  gap: 10px;\n}\n\n.eyebrow {\n  font-size: 12px;\n  font-weight: 600;\n  letter-spacing: 0.04em;\n  text-transform: uppercase;\n  color: var(--themarr-primary);\n}\n\n.hero-title {\n  font-size: 26px;\n  font-weight: 600;\n  letter-spacing: -0.01em;\n  line-height: 1.2;\n}\n\n.hero-description {\n  max-width: 560px;\n  font-size: 14px;\n  line-height: 1.5;\n  color: var(--themarr-muted-foreground);\n}\n\n.hero-actions {\n  display: flex;\n  gap: 8px;\n  padding-top: 6px;\n}\n\n.btn {\n  padding: 9px 16px;\n  border-radius: calc(var(--themarr-radius) - 2px);\n  font-size: 14px;\n}\n\n.btn-primary {\n  background: var(--themarr-primary);\n  color: var(--themarr-primary-foreground);\n  font-weight: 600;\n}\n\n.btn-secondary {\n  background: var(--themarr-secondary);\n  color: var(--themarr-secondary-foreground);\n  font-weight: 500;\n}\n\n/* Trending */\n\n.trending {\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.trending-head {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n.trending-title {\n  font-size: 17px;\n  font-weight: 600;\n}\n\n.chip {\n  padding: 4px 10px;\n  border-radius: 999px;\n  color: var(--themarr-muted-foreground);\n}\n\n.chip.is-active {\n  background: var(--themarr-accent);\n  color: var(--themarr-accent-foreground);\n  font-weight: 600;\n}\n\n.posters {\n  display: grid;\n  grid-template-columns: repeat(7, minmax(0, 1fr));\n  gap: 12px;\n}\n\n.poster {\n  position: relative;\n  height: 200px;\n  overflow: hidden;\n  border: 1px solid var(--themarr-border);\n  border-radius: var(--themarr-radius);\n}\n\n.poster-1 {\n  background: var(--themarr-chart-1);\n}\n\n.poster-2 {\n  background: var(--themarr-chart-2);\n}\n\n.poster-3 {\n  background: var(--themarr-chart-3);\n}\n\n.poster-4 {\n  background: var(--themarr-chart-4);\n}\n\n.poster-5 {\n  background: var(--themarr-chart-5);\n}\n\n.poster-6 {\n  background: var(--themarr-secondary);\n}\n\n.status {\n  position: absolute;\n  top: 8px;\n  right: 8px;\n  padding: 3px 7px;\n  border-radius: 999px;\n  font-size: 10px;\n  font-weight: 600;\n}\n\n.status-available {\n  background: var(--themarr-success);\n  color: var(--themarr-success-foreground);\n}\n\n.status-requested {\n  background: var(--themarr-info);\n  color: var(--themarr-info-foreground);\n}\n\n.status-pending {\n  background: var(--themarr-warning);\n  color: var(--themarr-warning-foreground);\n}\n\n.poster-title {\n  position: absolute;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  padding: 8px;\n  border-top: 1px solid var(--themarr-border);\n  background: var(--themarr-card);\n  color: var(--themarr-card-foreground);\n  font-size: 12px;\n  font-weight: 600;\n}\n"
